export interface ProductData {
  id: number;
  name: string;
  dosage: string;
  usage: string;
  isETC: boolean;
  listPrice: string;
  idecoPrice: string;
  manufacturer: string;
  description: string;
  imageBase64?: string;
  mimeType?: string;
  aspectRatio: 'vertical' | 'horizontal'; // New field for layout selection
}

export interface GeneratedResult {
  id: number;
  prompt: string;
  status: 'pending' | 'loading' | 'success' | 'error';
}

export enum AppState {
  IDLE,
  PROCESSING,
  COMPLETE
}

export interface PromptTemplate {
  name: string;
  prompt: string;
  keywords: string[];
}

export interface UploadedFile {
  name: string;
  type: string;
  size: number;
  base64: string;
  isProcessing?: boolean;
}

export interface BaseElement {
  id: number;
  x: number;
  y: number;
  width: number;
  height: number;
  rotation: number;
  skewX: number;
  skewY: number;
}

export interface TextProperties extends BaseElement {
  type: 'text';
  text: string;
  fontSize: number;
  fontFamily: string;
  color: string;
  isBold: boolean;
  isItalic: boolean;
  isUnderline: boolean;
  textAlign: 'left' | 'center' | 'right';
  lineHeight: number;
  shadowEnabled: boolean;
  shadowColor: string;
  shadowBlur: number;
  shadowOffsetX: number;
  shadowOffsetY: number;
  strokeEnabled: boolean;
  strokeColor: string;
  strokeWidth: number;
  colorRanges: { start: number; end: number; color: string }[];
  fontSizeRanges: { start: number; end: number; fontSize: number }[];
}

export interface ImageProperties extends BaseElement {
  type: 'image';
  src: string;
  imageElement?: HTMLImageElement;
  aspectRatio: number;
  shadowEnabled: boolean;
  shadowColor: string;
  shadowBlur: number;
  shadowOffsetX: number;
  shadowOffsetY: number;
  strokeEnabled: boolean;
  strokeColor: string;
  strokeWidth: number;
}

export interface BannerProperties extends BaseElement {
  type: 'banner';
  shape: 'rectangle' | 'ellipse' | 'diamond';
  backgroundColor: string;
  shadowEnabled: boolean;
  shadowColor: string;
  shadowBlur: number;
  shadowOffsetX: number;
  shadowOffsetY: number;
  strokeEnabled: boolean;
  strokeColor: string;
  strokeWidth: number;
}

export type CanvasElement = TextProperties | ImageProperties | BannerProperties;

export interface ExcelMapping {
  name: string;
  dosage: string;
  usage: string;
  listPrice: string;
  idecoPrice: string;
  manufacturer: string;
  packaging: string; // New field for packaging specification
}

import React, { useState, useRef, useMemo, useEffect } from 'react';
import * as XLSX from 'xlsx';
import { Upload, X, ArrowRight, Table, Check, AlertCircle, Search, RefreshCw, FileText, Save } from 'lucide-react';
import { ProductData, ExcelMapping } from '../types';

interface ExcelImportModalProps {
  isOpen: boolean;
  onClose: () => void;
  onImport: (products: ProductData[], rawData: any[], mapping: ExcelMapping) => void;
  onSave: (rawData: any[], mapping: ExcelMapping) => void;
  savedData?: any[];
  savedMapping?: ExcelMapping;
}

type ExcelRow = Record<string, any>;

const MAPPING_FIELDS: { key: keyof ExcelMapping; label: string }[] = [
  { key: 'name', label: 'Tên Thuốc' },
  { key: 'dosage', label: 'Hàm Lượng' },
  { key: 'usage', label: 'Công Dụng' },
  { key: 'packaging', label: 'Quy Cách (Đóng gói)' }, // Added packaging field
  { key: 'listPrice', label: 'Giá Niêm Yết' },
  { key: 'idecoPrice', label: 'Giá IDECO' },
  { key: 'manufacturer', label: 'Nhà Sản Xuất' },
];

export const ExcelImportModal: React.FC<ExcelImportModalProps> = ({ isOpen, onClose, onImport, onSave, savedData = [], savedMapping }) => {
  const [step, setStep] = useState<1 | 2>(1); // 1: Upload, 2: Map & Select
  const [data, setData] = useState<ExcelRow[]>([]);
  const [columns, setColumns] = useState<string[]>([]);
  const [mapping, setMapping] = useState<ExcelMapping>({
    name: '', dosage: '', usage: '', listPrice: '', idecoPrice: '', manufacturer: '', packaging: ''
  });
  const [selectedIndices, setSelectedIndices] = useState<Set<number>>(new Set());
  const [searchQuery, setSearchQuery] = useState('');
  const [isAutoLoaded, setIsAutoLoaded] = useState(false);
  const [isSaved, setIsSaved] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Initialize from saved data when opened
  useEffect(() => {
    if (isOpen) {
        if (savedData && savedData.length > 0) {
            setData(savedData);
            // Derive columns from the first row of saved data
            const cols = Object.keys(savedData[0]);
            setColumns(cols);

            if (savedMapping) {
                // Ensure legacy saved mappings have the packaging field
                setMapping({ ...savedMapping, packaging: savedMapping.packaging || '' });
            }

            setStep(2);
            setIsAutoLoaded(true);
            setIsSaved(true); // Since it came from saved storage, it is 'saved'
        } else {
            // No saved data, start at upload
            reset();
        }
    }
  }, [isOpen]); // Depend only on isOpen to avoid resetting during interaction

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (evt) => {
      try {
        const bstr = evt.target?.result;
        const wb = XLSX.read(bstr, { type: 'binary' });
        const wsname = wb.SheetNames[0];
        const ws = wb.Sheets[wsname];
        const jsonData = XLSX.utils.sheet_to_json<ExcelRow>(ws, { header: 1 });

        if (jsonData.length > 0) {
          const headers = jsonData[0] as string[];
          const cleanHeaders = headers.map(h => String(h).trim());
          setColumns(cleanHeaders);

          const rows = XLSX.utils.sheet_to_json<ExcelRow>(ws, { header: cleanHeaders });
          setData(rows);

          // Auto-guess mapping
          const newMapping: ExcelMapping = { name: '', dosage: '', usage: '', listPrice: '', idecoPrice: '', manufacturer: '', packaging: '' };
          cleanHeaders.forEach(col => {
             const lower = col.toLowerCase();
             if (lower.includes('tên thuốc')) newMapping.name = col;
             else if (lower.includes('hàm lượng') || lower.includes('nồng độ')) newMapping.dosage = col;
             else if (lower.includes('công dụng')) newMapping.usage = col;
             else if (lower.includes('quy cách') || lower.includes('đóng gói')) newMapping.packaging = col; // Auto-guess packaging
             else if (lower.includes('đơn giá hộp') || lower.includes('giá niêm yết')) newMapping.listPrice = col;
             else if (lower.includes('giá mua 6') || lower.includes('ideco')) newMapping.idecoPrice = col;
             else if (lower.includes('đơn vị sx') || lower.includes('nhà sản xuất')) newMapping.manufacturer = col;
          });
          setMapping(newMapping);

          setStep(2);
          setIsAutoLoaded(false);
          setIsSaved(false); // New upload is not saved yet
        }
      } catch (error) {
        console.error("Error parsing excel", error);
        alert("Lỗi đọc file Excel. Vui lòng thử lại.");
      }
    };
    reader.readAsBinaryString(file);
  };

  const handleMappingChange = (field: keyof ExcelMapping, column: string) => {
    setMapping(prev => ({ ...prev, [field]: column }));
    setIsSaved(false); // Mapping changed, status is unsaved
  };

  const toggleRowSelection = (originalIndex: number) => {
    const newSet = new Set(selectedIndices);
    if (newSet.has(originalIndex)) newSet.delete(originalIndex);
    else newSet.add(originalIndex);
    setSelectedIndices(newSet);
  };

  // Filter data based on search
  const filteredData = useMemo(() => {
    if (!searchQuery.trim()) return data.map((row, idx) => ({ row, originalIndex: idx }));
    const lowerQuery = searchQuery.toLowerCase();
    const searchCol = mapping.name || columns[0]; // Search in mapped Name col or first col
    return data
        .map((row, idx) => ({ row, originalIndex: idx }))
        .filter(({ row }) => {
            const val = row[searchCol];
            return val && String(val).toLowerCase().includes(lowerQuery);
        });
  }, [data, searchQuery, mapping.name, columns]);

  const handleManualSave = () => {
      onSave(data, mapping);
      setIsSaved(true);
  };

  const handleApply = () => {
    const selectedRows = data.filter((_, idx) => selectedIndices.has(idx));
    if (selectedRows.length === 0) {
      alert("Vui lòng chọn ít nhất một sản phẩm từ danh sách.");
      return;
    }

    const formatPrice = (val: any) => {
        if (typeof val === 'number') return val.toLocaleString('vi-VN') + ' đ';
        return String(val);
    };

    const newProducts: ProductData[] = selectedRows.map((row, idx) => {
      // Get basic price string
      const rawListPrice = row[mapping.listPrice] ? formatPrice(row[mapping.listPrice]) : '';
      const rawIdecoPrice = row[mapping.idecoPrice] ? formatPrice(row[mapping.idecoPrice]) : '';

      // Get packaging spec
      const packaging = row[mapping.packaging] ? String(row[mapping.packaging]) : '';

      // Combine: Price / Packaging
      const listPrice = rawListPrice + (packaging && rawListPrice ? ` / ${packaging}` : '');
      const idecoPrice = rawIdecoPrice + (packaging && rawIdecoPrice ? ` / ${packaging}` : '');

      return {
        id: idx + 1,
        name: row[mapping.name] ? String(row[mapping.name]) : '',
        dosage: row[mapping.dosage] ? String(row[mapping.dosage]) : '',
        usage: row[mapping.usage] ? String(row[mapping.usage]) : '',
        listPrice: listPrice,
        idecoPrice: idecoPrice,
        manufacturer: row[mapping.manufacturer] ? String(row[mapping.manufacturer]) : '',
        isETC: false,
        description: '',
        aspectRatio: 'vertical'
      };
    });

    // Pass processed products AND raw data + mapping for future use
    onImport(newProducts.slice(0, 3), data, mapping);
    onClose();
  };

  const reset = () => {
      setStep(1);
      setData([]);
      setColumns([]);
      setMapping({ name: '', dosage: '', usage: '', listPrice: '', idecoPrice: '', manufacturer: '', packaging: '' });
      setSelectedIndices(new Set());
      setSearchQuery('');
      setIsAutoLoaded(false);
      setIsSaved(false);
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4 animate-in fade-in duration-200">
      <div className="bg-white rounded-xl shadow-2xl w-full max-w-5xl max-h-[90vh] flex flex-col overflow-hidden">

        {/* Header */}
        <div className="px-6 py-4 border-b border-slate-200 flex justify-between items-center bg-slate-50">
            <h3 className="text-lg font-bold text-slate-800 flex items-center gap-2">
                <div className="p-2 bg-green-100 text-green-700 rounded-lg">
                    <Table className="w-5 h-5" />
                </div>
                {step === 1 ? 'Nhập Dữ Liệu Từ Excel' : 'Chọn Sản Phẩm'}
            </h3>
            <button onClick={onClose} className="text-slate-400 hover:text-slate-600 p-2 hover:bg-slate-100 rounded-full transition-colors">
                <X className="w-5 h-5" />
            </button>
        </div>

        {/* Content */}
        <div className="flex-1 overflow-y-auto p-6 custom-scrollbar">
            {step === 1 ? (
                <div className="h-full flex flex-col items-center justify-center py-12 border-2 border-dashed border-slate-300 rounded-xl bg-slate-50 hover:bg-slate-100 transition-colors cursor-pointer"
                     onClick={() => fileInputRef.current?.click()}>
                    <input type="file" ref={fileInputRef} onChange={handleFileUpload} accept=".xlsx, .xls" className="hidden" />
                    <Upload className="w-16 h-16 text-slate-300 mb-4" />
                    <p className="text-lg font-medium text-slate-600">Click để tải file Excel (.xlsx, .xls)</p>
                    <p className="text-sm text-slate-400 mt-2">Hỗ trợ bảng mã Unicode (UTF-8)</p>
                    <div className="mt-8 text-xs text-slate-400 text-center max-w-md">
                        <p className="font-semibold mb-1">Cấu trúc đề xuất:</p>
                        TT | Tên thuốc | Hàm lượng | Công dụng | Đơn giá | Nhà SX | Quy cách
                    </div>
                </div>
            ) : (
                <div className="space-y-6">
                    {/* Auto-load Banner */}
                    {isAutoLoaded && (
                        <div className="bg-blue-50 border border-blue-100 p-3 rounded-lg flex justify-between items-center text-sm text-blue-700">
                            <span className="flex items-center gap-2">
                                <FileText className="w-4 h-4" />
                                Đã tự động tải danh sách từ lần nhập trước.
                            </span>
                            <button 
                                onClick={reset}
                                className="text-blue-600 hover:text-blue-800 font-semibold underline"
                            >
                                Nhập file khác
                            </button>
                        </div>
                    )}

                    {/* Mapping Section */}
                    <div className="bg-slate-50 p-4 rounded-xl border border-slate-200">
                        <h4 className="font-semibold text-slate-700 mb-3 flex items-center gap-2">
                             <ArrowRight className="w-4 h-4 text-indigo-500" /> 
                             Bước 1: So chiếu cột dữ liệu
                        </h4>
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                            {MAPPING_FIELDS.map(field => (
                                <div key={field.key}>
                                    <label className="block text-xs font-semibold text-slate-500 mb-1">{field.label}</label>
                                    <select 
                                        className="w-full text-sm border-slate-300 rounded-lg shadow-sm focus:border-indigo-500 focus:ring-indigo-500"
                                        value={mapping[field.key] || ''}
                                        onChange={(e) => handleMappingChange(field.key, e.target.value)}
                                    >
                                        <option value="">-- Không chọn --</option>
                                        {columns.map(col => (
                                            <option key={col} value={col}>{col}</option>
                                        ))}
                                    </select>
                                </div>
                            ))}
                        </div>
                    </div>

                    {/* Data Table with Search */}
                    <div className="space-y-3">
                        <div className="flex flex-col md:flex-row justify-between items-end md:items-center gap-3">
                            <h4 className="font-semibold text-slate-700 flex items-center gap-2">
                                <div className="flex items-center gap-2">
                                    <Check className="w-4 h-4 text-indigo-500" /> 
                                    Bước 2: Chọn sản phẩm (Tối đa 3)
                                </div>
                                <span className="text-xs font-normal text-slate-500 bg-white px-2 py-0.5 rounded border border-slate-200">Đã chọn: {selectedIndices.size}</span>
                            </h4>

                            {/* Search Input */}
                            <div className="relative w-full md:w-64">
                                <input
                                    type="text"
                                    placeholder="Tìm tên thuốc..."
                                    value={searchQuery}
                                    onChange={(e) => setSearchQuery(e.target.value)}
                                    className="w-full pl-9 pr-3 py-1.5 text-sm border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 outline-none"
                                />
                                <Search className="w-4 h-4 text-slate-400 absolute left-3 top-2" />
                            </div>
                        </div>

                        <div className="border border-slate-200 rounded-lg overflow-hidden">
                            <div className="overflow-x-auto max-h-[300px]">
                                <table className="w-full text-sm text-left">
                                    <thead className="bg-slate-100 text-slate-600 font-semibold sticky top-0 z-10">
                                        <tr>
                                            <th className="p-3 w-10 text-center">
                                                <input type="checkbox" disabled />
                                            </th>
                                            {columns.map(col => (
                                                <th key={col} className="p-3 whitespace-nowrap">{col}</th>
                                            ))}
                                        </tr>
                                    </thead>
                                    <tbody className="divide-y divide-slate-100">
                                        {filteredData.length > 0 ? (
                                            filteredData.map(({ row, originalIndex }) => (
                                                <tr 
                                                    key={originalIndex} 
                                                    className={`hover:bg-indigo-50 cursor-pointer transition-colors ${selectedIndices.has(originalIndex) ? 'bg-indigo-50' : ''}`}
                                                    onClick={() => toggleRowSelection(originalIndex)}
                                                >
                                                    <td className="p-3 text-center" onClick={(e) => e.stopPropagation()}>
                                                        <input 
                                                            type="checkbox" 
                                                            checked={selectedIndices.has(originalIndex)}
                                                            onChange={() => toggleRowSelection(originalIndex)}
                                                            className="rounded text-indigo-600 focus:ring-indigo-500"
                                                        />
                                                    </td>
                                                    {columns.map(col => (
                                                        <td key={`${originalIndex}-${col}`} className="p-3 whitespace-nowrap max-w-[200px] truncate">
                                                            {row[col]}
                                                        </td>
                                                    ))}
                                                </tr>
                                            ))
                                        ) : (
                                            <tr>
                                                <td colSpan={columns.length + 1} className="p-8 text-center text-slate-500">
                                                    Không tìm thấy kết quả phù hợp.
                                                </td>
                                            </tr>
                                        )}
                                    </tbody>
                                </table>
                            </div>
                        </div>
                         {selectedIndices.size > 3 && (
                            <div className="mt-2 text-xs text-amber-600 flex items-center gap-1">
                                <AlertCircle className="w-3 h-3" />
                                Lưu ý: Chỉ 3 sản phẩm đầu tiên được chọn sẽ được nhập vào form.
                            </div>
                        )}
                    </div>
                </div>
            )}
        </div>

        {/* Footer */}
        <div className="px-6 py-4 border-t border-slate-200 bg-slate-50 flex justify-end gap-3">
             {step === 2 && (
                <>
                    <button 
                        onClick={reset}
                        className="px-4 py-2 text-sm font-medium text-slate-600 hover:bg-slate-200 rounded-lg transition-colors flex items-center gap-2"
                    >
                        <RefreshCw className="w-4 h-4" />
                        Nhập File Khác
                    </button>
                    <button 
                        onClick={handleManualSave}
                        disabled={isSaved}
                        className={`px-4 py-2 text-sm font-bold rounded-lg transition-colors flex items-center gap-2 border 
                            ${isSaved 
                                ? 'bg-green-50 text-green-700 border-green-200 cursor-default' 
                                : 'bg-white text-emerald-600 border-emerald-600 hover:bg-emerald-50'
                            }`}
                    >
                        {isSaved ? <Check className="w-4 h-4" /> : <Save className="w-4 h-4" />}
                        {isSaved ? 'Đã Lưu Dữ Liệu' : 'Lưu Dữ Liệu'}
                    </button>
                </>
             )}
            <button 
                onClick={onClose}
                className="px-4 py-2 text-sm font-medium text-slate-600 hover:bg-slate-200 rounded-lg transition-colors"
            >
                Hủy Bỏ
            </button>
            {step === 2 && (
                <button 
                    onClick={handleApply}
                    disabled={selectedIndices.size === 0}
                    className="px-6 py-2 text-sm font-bold text-white bg-indigo-600 hover:bg-indigo-700 rounded-lg shadow-md transition-colors disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2"
                >
                    <Check className="w-4 h-4" />
                    Nhập vào 3 ô SP
                </button>
            )}
        </div>

      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { ProductForm } from './components/ProductForm';
import { ResultDisplay } from './components/ResultDisplay';
import { ExternalToolModal } from './components/ExternalToolModal';
import { ExcelImportModal } from './components/ExcelImportModal';
import { ProductData, GeneratedResult, AppState, ExcelMapping } from './types';
import { generateOptimizedPrompt } from './services/geminiService';
import { PenTool, BrainCircuit, Sparkles, Bot, Table, Image } from 'lucide-react';
import useLocalStorage from './hooks/useLocalStorage';

// Initial Empty Product
const createEmptyProduct = (id: number): ProductData => ({
  id,
  name: '',
  dosage: '',
  usage: '',
  isETC: false,
  listPrice: '',
  idecoPrice: '',
  manufacturer: '',
  description: '',
  imageBase64: undefined,
  mimeType: undefined,
  aspectRatio: 'vertical'
});

const App: React.FC = () => {
  // State for 3 products
  const [products, setProducts] = useState<ProductData[]>([
    createEmptyProduct(1),
    createEmptyProduct(2),
    createEmptyProduct(3)
  ]);

  const [activeTab, setActiveTab] = useState<number>(1);
  const [results, setResults] = useState<GeneratedResult[]>([
    { id: 1, prompt: '', status: 'pending' },
    { id: 2, prompt: '', status: 'pending' },
    { id: 3, prompt: '', status: 'pending' }
  ]);

  const [appState, setAppState] = useState<AppState>(AppState.IDLE);

  // Persistent Storage for Excel Library
  const [masterLibrary, setMasterLibrary] = useLocalStorage<any[]>('excelMasterLibrary', []);
  const [columnMapping, setColumnMapping] = useLocalStorage<ExcelMapping>('excelColumnMapping', {
    name: '', dosage: '', usage: '', listPrice: '', idecoPrice: '', manufacturer: '', packaging: ''
  });

  // External Tool Modal State
  const [externalTool, setExternalTool] = useState<{ isOpen: boolean; type: 'gen' | 'mind' | 'image' | null }>({
    isOpen: false,
    type: null
  });

  // Excel Modal State
  const [excelModalOpen, setExcelModalOpen] = useState(false);

  const handleFieldChange = (id: number, field: keyof ProductData, value: string | boolean) => {
    setProducts(prev => prev.map(p => p.id === id ? { ...p, [field]: value } : p));
  };

  // Handle Image Upload and conversion to Base64
  const handleImageUpload = (id: number, file: File) => {
    if (file.size > 5 * 1024 * 1024) {
      alert("Ảnh quá lớn. Vui lòng chọn ảnh dưới 5MB.");
      return;
    }

    const reader = new FileReader();
    reader.onloadend = () => {
      const base64String = reader.result as string;
      setProducts(prev => prev.map(p => p.id === id ? { 
        ...p, 
        imageBase64: base64String,
        mimeType: file.type
      } : p));
    };
    reader.readAsDataURL(file);
  };

  const handleRemoveImage = (id: number) => {
    setProducts(prev => prev.map(p => p.id === id ? { ...p, imageBase64: undefined, mimeType: undefined } : p));
  };

  const handleGenerateAll = async () => {
    if (!process.env.API_KEY) {
        alert("Vui lòng cấu hình API Key. (Environment variable API_KEY is missing)");
        return;
    }

    setAppState(AppState.PROCESSING);

    setResults(prev => prev.map(r => {
        const prod = products.find(p => p.id === r.id);
        if (prod && prod.name) return { ...r, status: 'loading', prompt: '' };
        return r;
    }));

    const promises = products.map(async (product) => {
      if (!product.name) return;

      try {
        const prompt = await generateOptimizedPrompt(product);
        setResults(prev => prev.map(r => r.id === product.id ? { ...r, prompt, status: 'success' } : r));
      } catch (error) {
        const errorMessage = error instanceof Error ? error.message : String(error);
        setResults(prev => prev.map(r => r.id === product.id ? { ...r, prompt: errorMessage, status: 'error' } : r));
      }
    });

    await Promise.all(promises);
    setAppState(AppState.COMPLETE);
  };

  const handleExcelImport = (importedProducts: ProductData[], rawData: any[], mapping: ExcelMapping) => {
    // Save to local storage
    setMasterLibrary(rawData);
    setColumnMapping(mapping);

    // Merge imported products into the first available slots or overwrite
    setProducts(prev => {
        const newProducts = [...prev];
        importedProducts.forEach((imp, index) => {
            if (index < 3) {
                newProducts[index] = {
                    ...createEmptyProduct(index + 1),
                    ...imp,
                    id: index + 1
                };
            }
        });
        return newProducts;
    });
  };

  // Explicitly save the library without importing into product slots
  const handleSaveLibrary = (rawData: any[], mapping: ExcelMapping) => {
    setMasterLibrary(rawData);
    setColumnMapping(mapping);
  };

  // When a product is selected from autocomplete in ProductForm
  const handleApplyProductFromLibrary = (productIndex: number, libraryItem: any) => {
    const formatPrice = (val: any) => {
        if (typeof val === 'number') return val.toLocaleString('vi-VN') + ' đ';
        if (!val) return '';
        return String(val);
    };

    const rawListPrice = libraryItem[columnMapping.listPrice] ? formatPrice(libraryItem[columnMapping.listPrice]) : '';
    const rawIdecoPrice = libraryItem[columnMapping.idecoPrice] ? formatPrice(libraryItem[columnMapping.idecoPrice]) : '';
    const packaging = libraryItem[columnMapping.packaging] ? String(libraryItem[columnMapping.packaging]) : '';

    const newProductData: Partial<ProductData> = {
        name: libraryItem[columnMapping.name] ? String(libraryItem[columnMapping.name]) : '',
        dosage: libraryItem[columnMapping.dosage] ? String(libraryItem[columnMapping.dosage]) : '',
        usage: libraryItem[columnMapping.usage] ? String(libraryItem[columnMapping.usage]) : '',
        listPrice: rawListPrice + (packaging && rawListPrice ? ` / ${packaging}` : ''),
        idecoPrice: rawIdecoPrice + (packaging && rawIdecoPrice ? ` / ${packaging}` : ''),
        manufacturer: libraryItem[columnMapping.manufacturer] ? String(libraryItem[columnMapping.manufacturer]) : '',
    };

    setProducts(prev => prev.map(p => p.id === productIndex ? { ...p, ...newProductData } : p));
  };

  const openTool = (type: 'gen' | 'mind' | 'image') => {
    setExternalTool({ isOpen: true, type });
  };

  const closeTool = () => {
    setExternalTool({ isOpen: false, type: null });
  };

  return (
    <div className="min-h-screen bg-slate-100 p-4 md:p-8 font-sans">
      <div className="max-w-7xl mx-auto space-y-6">

        {/* Header */}
        <header className="flex flex-col md:flex-row items-center justify-between pb-4 gap-4">
          <div className="flex items-center gap-3">
            <div className="bg-indigo-600 text-white p-2.5 rounded-xl shadow-lg">
              <PenTool className="w-6 h-6" />
            </div>
            <div>
              <h1 className="text-2xl md:text-3xl font-extrabold text-slate-800 tracking-tight">
                Pharma Prompt Generator
              </h1>
              <p className="text-slate-500 text-sm font-medium">
                Tạo prompt hàng loạt (3 SP) kèm phân tích hình ảnh AI
              </p>
            </div>
          </div>

          {/* Right Side Tools */}
          <div className="flex gap-3">
             <button
              onClick={() => setExcelModalOpen(true)}
              className="flex items-center gap-2 px-4 py-2 bg-white text-emerald-700 font-semibold rounded-lg shadow-sm border border-emerald-200 hover:bg-emerald-50 hover:border-emerald-300 transition-all active:scale-95"
            >
              <Table className="w-5 h-5" />
              <span>Nhập Excel</span>
            </button>
            <button
              onClick={() => openTool('image')}
              className="flex items-center gap-2 px-4 py-2 bg-gradient-to-r from-pink-500 to-rose-500 text-white font-semibold rounded-lg shadow-md hover:shadow-lg transition-all active:scale-95"
            >
              <Image className="w-5 h-5" />
              <span>Tạo Ảnh</span>
            </button>
            <button
              onClick={() => openTool('mind')}
              className="flex items-center gap-2 px-4 py-2 bg-gradient-to-r from-purple-600 to-indigo-600 text-white font-semibold rounded-lg shadow-md hover:shadow-lg transition-all active:scale-95"
            >
              <BrainCircuit className="w-5 h-5" />
              <span>Mind</span>
            </button>
          </div>
        </header>

        {/* Main Grid */}
        <main className="grid grid-cols-1 lg:grid-cols-12 gap-6 items-start">

          {/* Left: Input Form (Spans 7 columns) */}
          <div className="lg:col-span-7 h-[800px]">
            <ProductForm 
              products={products}
              activeTab={activeTab}
              onTabChange={setActiveTab}
              onChange={handleFieldChange}
              onImageUpload={handleImageUpload}
              onRemoveImage={handleRemoveImage}
              onSubmit={handleGenerateAll}
              isProcessing={appState === AppState.PROCESSING}
              masterLibrary={masterLibrary}
              columnMapping={columnMapping}
              onApplyLibraryProduct={handleApplyProductFromLibrary}
            />
          </div>

          {/* Right: Results (Spans 5 columns) */}
          <div className="lg:col-span-5 h-[800px]">
            <ResultDisplay 
              results={results}
              appState={appState}
            />
          </div>

        </main>
      </div>

      {/* External Tool Modal */}
      <ExternalToolModal 
        isOpen={externalTool.isOpen}
        onClose={closeTool}
        url={
            externalTool.type === 'gen' ? 'https://lmarena.ai/' : 
            externalTool.type === 'image' ? 'https://ttshub.com/banana/' :
            'https://geminigen.ai'
        }
        title={
            externalTool.type === 'gen' ? 'LM Arena' : 
            externalTool.type === 'image' ? 'Banana Image Gen' :
            'GeminiGen AI'
        }
        icon={
            externalTool.type === 'gen' ? <Bot className="w-5 h-5"/> : 
            externalTool.type === 'image' ? <Image className="w-5 h-5"/> :
            <BrainCircuit className="w-5 h-5"/>
        }
      />

      {/* Excel Import Modal */}
      <ExcelImportModal 
        isOpen={excelModalOpen}
        onClose={() => setExcelModalOpen(false)}
        onImport={handleExcelImport}
        onSave={handleSaveLibrary}
        savedData={masterLibrary}
        savedMapping={columnMapping}
      />
    </div>
  );
};

export default App;

import React, { useRef, useState, useMemo, useEffect } from 'react';
import { ProductData, ExcelMapping } from '../types';
import { Pill, DollarSign, Factory, FileText, Tag, Upload, Trash2, HeartPulse, AlertCircle, Smartphone, Monitor, Quote, Search, Link as LinkIcon, Download, X } from 'lucide-react';
import { Sparkles } from 'lucide-react';

interface ProductFormProps {
  products: ProductData[];
  activeTab: number;
  onTabChange: (id: number) => void;
  onChange: (id: number, field: keyof ProductData, value: string | boolean) => void;
  onImageUpload: (id: number, file: File) => void;
  onRemoveImage: (id: number) => void;
  onSubmit: () => void;
  isProcessing: boolean;
  masterLibrary?: any[];
  columnMapping?: ExcelMapping;
  onApplyLibraryProduct?: (id: number, libraryItem: any) => void;
}

const PROMPT_TEMPLATES = [
  {
    id: 'female_patient',
    label: '👩 Nữ bệnh nhân cầm thuốc',
    text: 'Tạo poster quảng cáo chuyên nghiệp, đẹp với nền sáng, rõ ràng chân thật. Một bệnh nhân nữ trung niên người Việt Nam, tay cầm sản phẩm, tươi cười mắt nhìn thẳng camera, tại phòng khám hiện đại.'
  },
  {
    id: 'doctor_consult',
    label: '👨‍⚕️ Bác sĩ & Bệnh nhân Nam',
    text: 'Tạo poster quảng cáo đẹp, nền sáng, màu sắc tươi sáng. Một Nam bệnh nhân người Việt Nam, tuổi trung niên ngồi khám với một Bác sĩ nam, đang cầm trên tay hộp sản phẩm theo ảnh đính kèm đưa về hướng bệnh nhân.'
