            </div>
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Công dụng (Dòng phụ)</label>
              <div className="relative">
                <input
                  type="text"
                  value={activeProduct.usage}
                  onChange={(e) => handleChange(e, 'usage')}
